def transform(grid):
    if not grid:
        return grid

    h = len(grid)
    w = len(grid[0])
    new_h = h * 2
    new_w = w * 2
    output = [[0] * new_w for _ in range(new_h)]

    # Copy original (no rotation) to top-left
    for i in range(h):
        for j in range(w):
            output[i][j] = grid[i][j]

    # Rotate 90° clockwise and place in top-right
    for i in range(h):
        for j in range(w):
            output[i][h + w - 1 - j] = grid[w - 1 - j][i]

    # Rotate 180° and place in bottom-left
    for i in range(h):
        for j in range(w):
            output[h + i][j] = grid[h - 1 - i][w - 1 - j]

    # Rotate 270° clockwise (90° counter-clockwise) and place in bottom-right
    for i in range(h):
        for j in range(w):
            output[h + i][w + j] = grid[j][w - 1 - h + i]

    return output
